    int length;
    if ((byteValue & 0x80) == 0x00) {
        length = 1; // 0xxxxxxx
    } else if ((byteValue & 0xE0) == 0xC0) {
        length = 2; // 110xxxxx
        if (bb.remaining() < 2) {
            throw new IOException("Incomplete UTF-8 sequence");
        }
        byteValue = bb.get(i + 1);
        sb.append((char) ((byteValue & 0x0F) << 6) | ((byteValue & 0xF0) >> 6));
    } else if ((byteValue & 0xF0) == 0xE0) {
        length = 3; // 1110xxxx
        if (bb.remaining() < 3) {
            throw new IOException("Incomplete UTF-8 sequence");
        }
        byteValue = bb.get(i + 1);
        byteValue = bb.get(i + 2);
        sb.append((char) ((byteValue & 0x0F) << 12) | ((byteValue & 0x3F) << 6) | ((byteValue & 0xF0) >> 6));
