    int newSize = super.capacity() + size;
    // Create a new byte array with the enlarged size and copy the existing data
    byte[] newBytes = new byte[newSize];
    System.arraycopy(super.array(), 0, newBytes, 0, length());
    // Update the superclass array with the new array
    super.array(newBytes);
    super.setSize(newSize);
}
