TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.left == null) {
        return node; // No rotation needed if node is null or left child is null.
    }

    TreeNode<T> newParent = node.left; // New parent becomes the left child of the original node.
    newParent.right = node; // Right child of the new parent becomes the original node.

    node.left = null; // Left child of the original node is set to null.
    node.parent = newParent; // New parent becomes the parent of the original node.

    return newParent; // New parent is returned as the new root of the original node.
}
