public TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.getLeft() == null) {
        return node; // No child to rotate
    }

    TreeNode<T> newParent = node.getLeft();
    newParent.setParent(node);
    node.setLeft(newParent.getRight());
    if (newParent.getRight() != null) {
        newParent.getRight().setParent(node);
    }
    node.setParent(newParent);
    if (node.getLeft() != null) {
        node.getLeft().setLeft(newParent);
    }
    newParent.setRight(node);
    return newParent;
}
