public static void addToClassPath(@SuppressWarnings("unchecked") Vector<URL> cpV, String dir) {
    try {
        URL directoryURL = new URL("file:" + dir);
        cpV.add(directoryURL);
        for (File f : directoryURL.toURI().toFile().listFiles()) {
            if (f.isDirectory()) {
                addToClassPath(cpV, f.getAbsolutePath());
            } else if (f.endsWith(".jar") || f.endsWith(".war") || f.endsWith(".ear")) {
                URL jarURL = f.toURI().toURL();
                cpV.add(jarURL);
            }
        }
    } catch (Exception e) {
        System.err.println("Error adding classpath for directory " + dir);
        e.printStackTrace();
    }
}
