public static void scheduleForDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File cannot be null");
    }

    if (file.isDirectory()) {
        deleteAnd recurseDelete(file);
    }

    Runtime.getRuntime().addShutdownHook(new Thread(() -> forceDelete(file)));
}

private static void deleteAnd recurseDelete(File directory) throws IOException {
    File[] files = directory.listFiles();
    if (files != null) {
        for (File file : files) {
            deleteAnd recurseDelete(file);
        }
    }
    directory.delete();
}
