public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    // Write message length
    out.write(Long.SIZE / 8);
    out.write(schema.id);

    // Seal the buffer
    Seal seal = seal(schema, buffer, new byte[256]);

    // Serialise the sealed buffer to the output stream
    out.write(seal.toByteArray());

    return schema.id + (int)(Long.SIZE / 8) + seal.size();
}
