    if (buffer == null) {
        throw new IllegalArgumentException("Buffer cannot be null");
    }

    // Write the length of the message to the output stream
    out.write(BufferUtils.intToBytes(message.length()));

    // Serialize the actual message to the output stream using the provided schema
    schema.writeTo(out, message);

    // Increment the size counter based on the number of bytes written
    return message.length();
}

