static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.toBytes(message, buffer);
    out.write(Integer.BYTES.length, buffer.position() - Integer.BYTES.length, Integer.BYTES);
    out.writeShort(buffer.position() - Integer.BYTES.length, size >> 16);
    out.writeShort(buffer.position() - Integer.BYTES.length, size);
    out.write(buffer.position() - Integer.BYTES.length, message);
    return 4 + size;
}
