public static Class<?>[] resolveArguments(Type genericType,Class<?> targetType) {
    // Check if genericType is not parameterized
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

    // Create an array to hold the resolved arguments
    Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];

    for (int i = 0; i < actualTypeArguments.length; i++) {
        // Check if the actualTypeArgument is a wildcard or a raw type
        if (actualTypeArguments[i] instanceof WildcardType || actualTypeArguments[i].equals(Object.class)) {
            resolvedArguments[i] = targetType;
        } else {
            // Resolve the actual type argument by looking it up in typeVariableMap
            resolvedArguments[i] = typeVariableMap.get(actualTypeArguments[i]);
            if (resolvedArguments[i] == null) {
                throw new IllegalArgumentException("Could not resolve type argument " + actualTypeArguments[i]);
            }
        }
    }

    return resolvedArguments;
}
