public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
  if (!(genericType instanceof ParameterizedType)) {
    return null;
  }
  ParameterizedType parameterizedType = (ParameterizedType) genericType;
  Type[] typeArguments = parameterizedType.getActualTypeArguments();
  List<Class<?>> resolvedArguments = new ArrayList<>();
  for (Type argType : typeArguments) {
    if (argType instanceof WildcardType) {
      Type[] extendsTypes = ((WildcardType) argType).getUpperBounds();
      for (Type extType : extendsTypes) {
        resolvedArguments.add(extType instanceof Class<?> ? (Class<?>) extType : null);
      }
    } else {
      resolvedArguments.add(activeClass(argType));
    }
  }
  if (targetType == genericType) {
    resolvedArguments.add(targetType);
  }
  return resolvedArguments.toArray(new Class<?>[resolvedArguments.size()]);
}
