public class DataProcessor {
    public static List<TimeRange> buildTimeRanges(long start, long end) {
        if (end - start <= FETCH_DATA_DURATION) {
            return Collections.singletonList(new TimeRange(start, end));
        } else {
            long splitPoint = start + (end - start) / 2;
            List<TimeRange> result = new ArrayList<>();
            result.add(new TimeRange(start, splitPoint));
            result.add(new TimeRange(splitPoint, end));
            return result;
        }
    }

    public static void main(String[] args) {
        // Example usage
        System.out.println(buildTimeRanges(100, 500)); // Output: [0-250]
