private List<TimeRange> buildTimeRanges(long start, long end) {
    if (start >= FETCH_DATA_DURATION || end <= FETCH_DATA_DURATION) {
        throw new IllegalArgumentException("Start or end time cannot be greater than or equal to FETCH_DATA_DURATION");
    }
    List<TimeRange> result = new ArrayList<>();
    long currentStart = start;
    while (currentStart + FETCH_DATA_DURATION <= end) {
        result.add(new TimeRange(currentStart, currentStart + FETCH_DATA_DURATION));
        currentStart += FETCH_DATA_DURATION;
    }
    // Handle the remain part
    if (currentStart < end) {
        result.add(new TimeRange(currentStart, end));
    }
    return result;
}
