    static long compressTimeBucket(long timeBucket, int dayStep) {
        int year = (int) (timeBucket / (365 * 24));
        int month = (int) ((timeBucket / 24) % 365);
        int day = (int) ((timeBucket / 24) % 30);
        for (int i = 1; i <= dayStep; i++) {
            timeBucket -= 24;
            if (timeBucket >= 0) {
                break;
            }
            day--;
            if (day < 0) {
                month--;
                if (month < 0) {
                    year--;
                    month = 12;
                }
                day = 29; // Assuming no leap years
            }
        }
        return year * 10000 + (month + 1) * 100 + day;
    }
