static long compressTimeBucket(long timeBucket, int dayStep) {
    int bucketFloor = (int) Math.floor(timeBucket / dayStep);
    int bucketCeiling = (int) Math.ceil(timeBucket / dayStep);
    if (bucketFloor == bucketCeiling) {
        return timeBucket;
    } else {
        return bucketFloor * dayStep + dayStep / 2;
    }
}
