public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int utf8Len = 0;
    int i = index;
    while (i < index + len) {
        // Read the current byte
        byte curr = ((char) str.charAt(i++)) & 0xFF;
        // Check each case to determine UTF-8 length
        if (curr <= 0x7F) {
            utf8Len++; // Single byte ASCII or continuation byte
        } else if (curr >= 0xC2 && curr <= 0xDF) {
            utf8Len += 2; // 2-byte UTF-8 character
        } else if (curr >= 0xE0 && curr <= 0xEF) {
            utf8Len += 3; // 3-byte UTF-8 character
        } else if (curr >= 0xF0 && curr <= 0xF7) {
            utf8Len += 4; // 4-byte UTF-8 character
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 sequence at index " + i);
        }
    }
    return utf8Len;
}
