    int utf8Length = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= '\u007F') {
            utf8Length++;
        } else if (c <= '\u07FF') {
            utf8Length += 2;
        } else if (c >= '\u0800') {
            utf8Length += 3;
        } else if (c >= '\u1000') {
            utf8Length += 4;
        } else {
            utf8Length += 5;
        }
    }
