public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || lb == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    int len = str.length();
    char[] chars = str.toCharArray();
    for (int i = 0; i < len; i++) {
        char c = chars[i];
        if (c >= 0 && c < Charcter.MAX_VALUE) {
            if (c >= 0x80) {
                lb.write(c);
                if (session != null) {
                    session.invalidateByte(c);
                }
            } else {
                int cVal = (int) c;
                if ((cVal & 0xC0) != 0x80) {
                    lb.write((byte) (128 | cVal));
                } else {
                    lb.write(cVal);
                }
            }
        } else {
            if (c >= 0x10000) {
                lb.write(0xF0);
                lb.write((byte)((c >> 18) & 0x3F));
                lb.write((byte)((c >> 12) & 0x3F));
                lb.write((byte)((c >> 6) & 0x3F));
                lb.write((byte)(c & 0x3F));
            } else if ((c & 0xD800) == 0xD800) {
                if (i + 1 < len && (chars[i + 1] & 0xDFF0) == 0xDC00) {
                    int mid = (c & 0x3FF) << 10 | (chars[i + 1] & 0x3FF);
                    lb.write((byte) (0xED));
                    lb.write((byte) ((mid >> 6) & 0x7F));
                    lb.write((byte)(mid & 0x3F));
                    i++;
                } else {
                    throw new IllegalArgumentException("Invalid UTF-16 character (high surrogate alone)");
                }
            } else if ((c & 0xD800) == 0xDC00) {
                throw new IllegalArgumentException("Invalid UTF-16 character (low surrogate alone)");
            } else {
                throw new IllegalArgumentException("Invalid UTF-16 character (surrogate pair required)");
            }
        }
    }
    return lb;
}
