  double midpoint = box.getMinX() + (box.getMaxX() - box.getMinX()) / 2;

  // Calculate the new bounding boxes
  Box2D leftBox = new Box2D(box.getMinX(), box.getY(), midpoint, box.getHeight());
  Box2D rightBox = new Box2D(midpoint, box.getY(), box.getMaxX(), box.getHeight());

  // Return the two resulting boxes as a pair
  return new Pair<>(leftBox, rightBox);
}
