public static int writeTo(final DataOutput out,LinkedBuffer node) throws IOException {
    if (out == null || node == null) {
        throw new IllegalArgumentException("Cannot write with null output or node");
    }
    int totalSize = 0;
    out.writeInt(node.getCount()); // Write the count of elements in the node
    for (int i = 0; i < node.getCount(); i++) {
        int size = node.get(i).length();
        totalSize += size;
        out.writeInt(size); // Write the size of each element
        out.write(node.get(i)); // Write the element bytes to the output
    }
    return totalSize;
}
