public static String unescapeJava(String str) throws Exception {
    if (str == null) return null;

    StringBuilder escaped = new StringBuilder();
    StringBuilder unescaped = new StringBuilder();
    char[] chars = str.toCharArray();
    int len = chars.length;
    int i = 0;

    while (i < len) {
        char c = chars[i];
        if (c == '\\') {
            i++; // Skip the escape character itself
            char nextChar = chars[i];
            switch (nextChar) {
                case 'n':
                    unescaped.append('\n');
                    break;
                case 't':
                    unescaped.append('\t');
                    break;
                case 'r':
                    unescaped.append('\r');
                    break;
                case '\'':
                    if (i + 1 < len && chars[i + 1] == '\'') {
                        unescaped.append('\''); // Escaped single quote
                        i++;
                    } else {
                        unescaped.append('n'); // Non-escaped single quote
                    }
                    break;
                case '"':
                    if (i + 1 < len && chars[i + 1] == '"') {
                        unescaped.append('"'); // Escaped double quote
                        i++;
                    } else {
                        unescaped.append('n'); // Non-escaped double quote
                    }
                    break;
                case '\\':
                    unescaped.append('\\'); // Escaped backslash
                    break;
                default:
                    unescaped.append(nextChar); // Handle other escape sequences
            }
        } else {
            unescaped.append(c); // Append unescaped characters
        }
        i++;
    }

    return unescaped.toString();
}
