                    case '\'':
                        escaped.append('\'");
                        break;
                    case '"':
                        escaped.append("\"");
                        break;
                    case '#':
                        int value = 0;
                        while (i + 1 < n && str.charAt(i + 1) >= '0' && str.charAt(i + 1) <= '9') {
                            value = (value << 3) + (value << 1) + Character.digit(str.charAt(i + 1), 10);
                            i++;
                        }
                        escaped.append((char) value);
                        break;
                    default:
                        // Handle other escape sequences here
                        escaped.append(c);
                        escaped.append(next);
                }
            } else {
                // Handle end of string with an escape sequence
                escaped.append(c);
            }
            i++;
        } else {
            escaped.append(c);
