public OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null || start == null || stop == null || dir < 0) {
        throw new IllegalArgumentException("Invalid input parameters");
    }
    Node current = start;
    try {
        while (current != stop) {
            if (predicate.test(current)) {
                return new OuterFaceCirculator(current);
            }
            current = dir > 0 ? current.getNext() : current.getPrevious();
        }
        return new OuterFaceCirculator(stop);
    } catch (Exception e) {
        LOG.error("Failed to select node on outer face", e);
        return null;
    }
}
