        // Return the byte vector with filled with null bytes
        return new ByteVector(byteLength, 0);
    }
    if (byteOffset + byteLength > byteArrayValue.length) {
        throw new IllegalArgumentException("byteOffset + byteLength > byteArrayValue.length");
    }

    // Enlarge the byte vector if necessary
    while (bytesVector.length < byteOffset + byteLength) {
        bytesVector = Arrays.copyOf(bytesVector, bytesVector.length * 2);
