import java.util.*;

public GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input sets cannot be null");
    }

    List<E> edges = new ArrayList<>(tour);
    Collections.sort(edges); // Ensure edges are in order for the current implementation

    GraphPath<V,E> path = new GraphPath<>();
    V lastNode = null;

    for (E edge : edges) {
        V fromNode = graph.edgeSource(edge);
        V toNode = graph.edgeTarget(edge);

        if (fromNode.equals(lastNode)) {
            path.moveToNextVertex(toNode);
        } else {
            path.moveToVertex(fromNode);
            path.moveToLastVertex(toNode);
        }

        lastNode = toNode;
    }

    return path;
}
