/**
 * Moves all vertices from the bucket with label  {@code minLabel} to the bucket with label 0.Clears the bucket with label  {@code minLabel}. Updates the labeling accordingly.
 * @param bucketsByLabel the buckets vertices are stored in
 * @param labels the labels of the vertices
 * @param minLabel the minimum value of the non-empty bucket
 */
private void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel) {
    Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
    bucketsByLabel.remove(minLabel);
    bucketsByLabel.add(0, minLabelBucket);

    int newLabel = 0;
    for (int i = minLabel + 1; i < bucketsByLabel.size(); i++) {
        bucketsByLabel.get(i - 1).addAll(bucketsByLabel.get(i));
        bucketsByLabel.remove(i);
        newLabel++;
    }
}
