public void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Find the vertices in the bucket with label minLabel
    List<Integer> vertices = new ArrayList<>();
    for (int i = 0; i < labels.size(); i++) {
        if (labels.get(i) == minLabel) {
            vertices.add(i);
        }
    }

    // Move the vertices to the bucket with label 0
    bucketsByLabel.get(0).addAll(vertices);

    // Clear the bucket with label minLabel
    bucketsByLabel.get(minLabel).clear();

    // Update the labels of the vertices
    for (int i = 0; i < vertices.size(); i++) {
        labels.set(vertices.get(i), 0);
    }
}
