private void moveAllListNodes(DoublyLinkedList<E> list) throws IOException, InterruptedException {
        synchronized (this) {
            ListNode<E> current = list.head;

            while (current != null) {
                ListNodeImpl<E> node = new ListNodeImpl<>(current.nodeValue);
                removeListNode(current);
                addListNode(node);
                current = current.next;
            }

            list.head = null;
            list.tail = null;
            list.size = 0;
        }
    }
}

