public static void selectRow(int row,JTable table,JScrollPane pane){
    // Ensure the table and JScrollPane are valid
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Both table and JScrollPane must be non-null");
    }

    // Select the specified row in the table
    table.getSelectionModel().setSelectionInterval(row, row);

    // Scroll the specified JScrollPane to the newly selected row
    pane.scrollToRow(table.getSelectedRow());

    // Delay the repaint() to have the table properly paint the newly selected row which may be offscreen
    new Timer(100, new ActionListener() {
        @Override
        public void actionPerformed(ActionEvent e) {
            table.repaint();
        }
    }).start();
}
```

