public static Type resolveBound(TypeVariable<?> typeVariable) {
    // Check if typeVariable is null
    if (typeVariable == null) {
        return Unknown.class;    
    }

    // Try to find implicit bounds
    for (Type genericType : typeVariable.getBounds()) {
        if (genericType instanceof WildcardType) {
            // Convert wildcard type to its upper bound
            WildcardType wildcardType = (WildcardType) genericType;
            return wildcardType.getUpperBound();    
        }
    }

    // Return Unknown.class if no bounds are found
    return Unknown.class;    
}
