private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices){
    int n = vertices.size();
    if (n < 3) {
        return true;
    }

    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue;
            }
            if (!isConnected(graph, v1, v2)) {
                return false;
            }
        }
    }

    return true;
}

private static <V,E> boolean isConnected(Graph<V,E> graph, V v1, V v2){
    return graph.containsEdge(v1, v2) || graph.containsEdge(v2, v1);
}
