public <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) throws IllegalArgumentException {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertices cannot be null.");
    }

    int numVertices = graph.vertexSet().size();
    if (vertices.size() > numVertices) {
        throw new IllegalArgumentException("The number of vertices to induce the subgraph from cannot exceed the number of vertices in the graph.");
    }

    Set<V> seen = new HashSet<>();
    for (V vertex : vertices) {
        if (!graph.containsVertex(vertex)) {
            throw new IllegalArgumentException("One or more specified vertices are not in the graph.");
        }
        seen.add(vertex);
    }

    for (E edge : graph.edgeSet()) {
        V sourceVertex = graph.getEdgeSource(edge);
        V targetVertex = graph.getEdgeTarget(edge);
        if (seen.contains(sourceVertex) && seen.contains(targetVertex)) {
            return false;
        }
    }

    return seen.size() == numVertices;
}
```

