        Set<V> neighbors = graph.neighbors(v);
        for (V w : vertices) {
            if (v.equals(w)) continue;
            if (!neighbors.contains(w) && !graph.findEdge(v, w) == null) {
                return false;
            }
        }
    }
    return true;
