private static <V,E>boolean isClique(Graph<V,E> graph,Set<V> vertices){
    int n = vertices.size();
    if (n < 2) {
        return true; // A graph with 0 or 1 vertex is always a clique.
    }

    Set<E> possibleEdges = new HashSet<>();
    for (Set<V> subset : combinations(vertices, 2)) {
        possibleEdges.add(graph.edge(subset.peekFirst(), subset.peekLast()));
    }

    for (Graph<V,E> inducedGraph : inducedSubgraphs(graph, vertices)) {
        if (inducedGraph.edges().size() != possibleEdges.size()) {
            return false; // The induced graph is not a clique.
        }
    }

    return true;
}
