private List<Integer> computeLowerBounds(List<K> keys) {
    // Check if the keys list is null
    if (keys == null || keys.isEmpty()) {
        throw new IllegalArgumentException("Cannot compute lower bounds with empty keys list");
    }

    // Sort the keys list
    Collections.sort(keys);

    // Initialize the list to store the lower bounds
    List<Integer> lowerBounds = new ArrayList<>();

    // Iterate through the sorted keys to compute the lower bounds
    for (int i = 0; i < keys.size() - 1; i++) {
        int currentKey = keys.get(i);
        int nextKey = keys.get(i + 1);
        lowerBounds.add(nextKey - currentKey);
    }

    return lowerBounds;
}
