private List<Integer> computeUpperBounds(List<K> keys) throws IndexException {
    List<Integer> upperBounds;
    if (keys == null || keys.isEmpty()) {
        // Invalid input, return an empty list
        return new ArrayList<>();
    }

    // Initialize upperBounds with the upper bound of the first element
    upperBounds = new ArrayList<>();
    upperBounds.add(Integer.MAX_VALUE);

    for (K key : keys) {
        // Compute the upper bound for the current key
        int newUpper bound = upperBounds.get(upperBounds.size() - 1);
        if (key.compareTo(newUpperBound) > 0) {
            upperBounds.add(key);
        } else {
            // Find the nearest upper bound smaller than the current key
